    ('vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class', 'Tour Huế đạp xe, nông trại hữu cơ và lớp nấu ăn', 'Tour Huế đạp xe, nông trại hữu cơ và lớp nấu ăn là chương trình đã được DanangTrip chuẩn hóa từ dữ liệu công khai của đơn vị tổ chức. Tour có thời lượng 8 Hours, giá tham khảo và lịch trình được đối chiếu từ nguồn gốc trước khi nhập vào hệ thống. Nội dung này đã được biên tập tiếng Việt ở mức sẵn sàng hiển thị, nhưng vẫn giữ tinh thần kiểm duyệt cuối cùng trước vận hành thương mại. Nguồn tham khảo: https://vmtravel.com/tours/hue-bicycle-tour/', 'Tour Huế đạp xe, nông trại hữu cơ và lớp nấu ăn, thời lượng 8 Hours, đã có giá, ảnh Cloudinary và lịch khởi hành tương lai.', '["Gặp hướng dẫn viên tại điểm hẹn và giới thiệu ngắn về văn hóa ẩm thực địa phương.","Ghé chợ, quán ăn hoặc điểm trải nghiệm ẩm thực theo lịch trình.","Thưởng thức các món đặc trưng và nghe câu chuyện về nguyên liệu, cách chế biến.","Tham gia lớp nấu ăn hoặc trải nghiệm ăn uống địa phương nếu có trong chương trình.","Kết thúc tour và nhận gợi ý thêm cho hành trình ăn uống tự túc."]'::json, '["Xe đưa đón theo chương trình","Hướng dẫn viên theo ngôn ngữ công bố của đơn vị tổ chức","Vé tham quan theo lịch trình nếu được ghi trong tour gốc","Nước uống hoặc bữa ăn theo mô tả của từng tour"]'::json, '["Chi phí cá nhân ngoài chương trình","Đồ uống, dịch vụ hoặc vé không được nêu trong phần bao gồm","Tiền tip cho hướng dẫn viên và tài xế nếu không được ghi rõ","Phụ thu phát sinh do thay đổi lịch trình, thời tiết hoặc yêu cầu riêng"]'::json, false, false),
    ('vmtravel-central-016-hue-cooking-class-tour-from-market-to-table', 'Tour lớp nấu ăn Huế từ chợ địa phương đến bàn ăn', 'Tour lớp nấu ăn Huế từ chợ địa phương đến bàn ăn là chương trình đã được DanangTrip chuẩn hóa từ dữ liệu công khai của đơn vị tổ chức. Tour có thời lượng 6 hours, giá tham khảo và lịch trình được đối chiếu từ nguồn gốc trước khi nhập vào hệ thống. Nội dung này đã được biên tập tiếng Việt ở mức sẵn sàng hiển thị, nhưng vẫn giữ tinh thần kiểm duyệt cuối cùng trước vận hành thương mại. Nguồn tham khảo: https://vmtravel.com/tours/hue-cooking-class-tour/', 'Tour lớp nấu ăn Huế từ chợ địa phương đến bàn ăn, thời lượng 6 hours, đã có giá, ảnh Cloudinary và lịch khởi hành tương lai.', '["Gặp hướng dẫn viên tại điểm hẹn và giới thiệu ngắn về văn hóa ẩm thực địa phương.","Ghé chợ, quán ăn hoặc điểm trải nghiệm ẩm thực theo lịch trình.","Thưởng thức các món đặc trưng và nghe câu chuyện về nguyên liệu, cách chế biến.","Tham gia lớp nấu ăn hoặc trải nghiệm ăn uống địa phương nếu có trong chương trình.","Kết thúc tour và nhận gợi ý thêm cho hành trình ăn uống tự túc."]'::json, '["Xe đưa đón theo chương trình","Hướng dẫn viên theo ngôn ngữ công bố của đơn vị tổ chức","Vé tham quan theo lịch trình nếu được ghi trong tour gốc","Nước uống hoặc bữa ăn theo mô tả của từng tour"]'::json, '["Chi phí cá nhân ngoài chương trình","Đồ uống, dịch vụ hoặc vé không được nêu trong phần bao gồm","Tiền tip cho hướng dẫn viên và tài xế nếu không được ghi rõ","Phụ thu phát sinh do thay đổi lịch trình, thời tiết hoặc yêu cầu riêng"]'::json, false, false),
