    ('vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45', 'Tour ẩm thực đường phố Huế', 'Tour ẩm thực đường phố Huế là chương trình đã được DanangTrip chuẩn hóa từ dữ liệu công khai của đơn vị tổ chức. Tour có thời lượng 5 Hours, giá tham khảo và lịch trình được đối chiếu từ nguồn gốc trước khi nhập vào hệ thống. Nội dung này đã được biên tập tiếng Việt ở mức sẵn sàng hiển thị, nhưng vẫn giữ tinh thần kiểm duyệt cuối cùng trước vận hành thương mại. Nguồn tham khảo: https://vmtravel.com/tours/hue-street-food-tour/', 'Tour ẩm thực đường phố Huế, thời lượng 5 Hours, đã có giá, ảnh Cloudinary và lịch khởi hành tương lai.', '["Gặp hướng dẫn viên tại điểm hẹn và giới thiệu ngắn về văn hóa ẩm thực địa phương.","Ghé chợ, quán ăn hoặc điểm trải nghiệm ẩm thực theo lịch trình.","Thưởng thức các món đặc trưng và nghe câu chuyện về nguyên liệu, cách chế biến.","Tham gia lớp nấu ăn hoặc trải nghiệm ăn uống địa phương nếu có trong chương trình.","Kết thúc tour và nhận gợi ý thêm cho hành trình ăn uống tự túc."]'::json, '["Xe đưa đón theo chương trình","Hướng dẫn viên theo ngôn ngữ công bố của đơn vị tổ chức","Vé tham quan theo lịch trình nếu được ghi trong tour gốc","Nước uống hoặc bữa ăn theo mô tả của từng tour"]'::json, '["Chi phí cá nhân ngoài chương trình","Đồ uống, dịch vụ hoặc vé không được nêu trong phần bao gồm","Tiền tip cho hướng dẫn viên và tài xế nếu không được ghi rõ","Phụ thu phát sinh do thay đổi lịch trình, thời tiết hoặc yêu cầu riêng"]'::json, false, false),
    ('vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an', 'Tour chùa Linh Ứng và Ngũ Hành Sơn từ Hội An', 'Tour chùa Linh Ứng và Ngũ Hành Sơn từ Hội An là chương trình đã được DanangTrip chuẩn hóa từ dữ liệu công khai của đơn vị tổ chức. Tour có thời lượng 6 Hours, giá tham khảo và lịch trình được đối chiếu từ nguồn gốc trước khi nhập vào hệ thống. Nội dung này đã được biên tập tiếng Việt ở mức sẵn sàng hiển thị, nhưng vẫn giữ tinh thần kiểm duyệt cuối cùng trước vận hành thương mại. Nguồn tham khảo: https://vmtravel.com/tours/marble-mountain-tour-from-hoi-an/', 'Tour chùa Linh Ứng và Ngũ Hành Sơn từ Hội An, thời lượng 6 Hours, đã có giá, ảnh Cloudinary và lịch khởi hành tương lai.', '["Đón khách từ Đà Nẵng, Hội An hoặc cảng theo xác nhận đặt tour.","Di chuyển đến Hội An và tham quan các điểm nổi bật của phố cổ.","Tìm hiểu kiến trúc, văn hóa thương cảng và các làng nghề hoặc khu chợ địa phương.","Có thời gian tự do chụp ảnh, mua sắm hoặc thưởng thức món địa phương.","Quay lại điểm đón, kết thúc chương trình."]'::json, '["Xe đưa đón theo chương trình","Hướng dẫn viên theo ngôn ngữ công bố của đơn vị tổ chức","Vé tham quan theo lịch trình nếu được ghi trong tour gốc","Nước uống hoặc bữa ăn theo mô tả của từng tour"]'::json, '["Chi phí cá nhân ngoài chương trình","Đồ uống, dịch vụ hoặc vé không được nêu trong phần bao gồm","Tiền tip cho hướng dẫn viên và tài xế nếu không được ghi rõ","Phụ thu phát sinh do thay đổi lịch trình, thời tiết hoặc yêu cầu riêng"]'::json, true, false),
    ('vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds', 'Tour golf Đà Nẵng 6 ngày 5 đêm cao cấp', 'Tour golf Đà Nẵng 6 ngày 5 đêm cao cấp là chương trình đã được DanangTrip chuẩn hóa từ dữ liệu công khai của đơn vị tổ chức. Tour có thời lượng 6 Days, giá tham khảo và lịch trình được đối chiếu từ nguồn gốc trước khi nhập vào hệ thống. Nội dung này đã được biên tập tiếng Việt ở mức sẵn sàng hiển thị, nhưng vẫn giữ tinh thần kiểm duyệt cuối cùng trước vận hành thương mại. Nguồn tham khảo: https://vmtravel.com/tours/luxury-da-nang-golf-tour-6-days/', 'Tour golf Đà Nẵng 6 ngày 5 đêm cao cấp, thời lượng 6 Days, đã có giá, ảnh Cloudinary và lịch khởi hành tương lai.', '["Đón khách và hỗ trợ di chuyển đến sân golf theo lịch trình.","Làm thủ tục tại sân, nhận thông tin tee time và các dịch vụ đi kèm.","Trải nghiệm vòng golf theo số ngày, số sân và số lượt chơi đã công bố.","Nghỉ ngơi, dùng bữa hoặc di chuyển giữa các điểm lưu trú theo chương trình.","Kết thúc hành trình và trả khách tại điểm đã xác nhận."]'::json, '["Lịch chơi golf theo chương trình","Xe đưa đón theo lịch trình","Hỗ trợ đặt sân và điều phối tee time","Dịch vụ lưu trú hoặc bữa ăn nếu được ghi trong tour gốc"]'::json, '["Chi phí cá nhân ngoài chương trình","Đồ uống, dịch vụ hoặc vé không được nêu trong phần bao gồm","Tiền tip cho hướng dẫn viên và tài xế nếu không được ghi rõ","Phụ thu phát sinh do thay đổi lịch trình, thời tiết hoặc yêu cầu riêng"]'::json, false, false),
    ('vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an', 'Tour Thánh địa Mỹ Sơn 1 ngày từ Hội An', 'Tour Thánh địa Mỹ Sơn 1 ngày từ Hội An là chương trình đã được DanangTrip chuẩn hóa từ dữ liệu công khai của đơn vị tổ chức. Tour có thời lượng Half day, giá tham khảo và lịch trình được đối chiếu từ nguồn gốc trước khi nhập vào hệ thống. Nội dung này đã được biên tập tiếng Việt ở mức sẵn sàng hiển thị, nhưng vẫn giữ tinh thần kiểm duyệt cuối cùng trước vận hành thương mại. Nguồn tham khảo: https://vmtravel.com/tours/my-son-sanctuary-from-hoi-an/', 'Tour Thánh địa Mỹ Sơn 1 ngày từ Hội An, thời lượng Half day, đã có giá, ảnh Cloudinary và lịch khởi hành tương lai.', '["Đón khách và di chuyển đến khu di sản Thánh địa Mỹ Sơn.","Tham quan các cụm tháp Chăm và nghe giới thiệu về lịch sử vương quốc Champa.","Xem biểu diễn văn hóa hoặc trải nghiệm địa phương nếu lịch vận hành phù hợp.","Dùng bữa hoặc nghỉ ngơi theo chương trình tour.","Trả khách tại điểm đón ban đầu."]'::json, '["Xe đưa đón theo chương trình","Hướng dẫn viên theo ngôn ngữ công bố của đơn vị tổ chức","Vé tham quan theo lịch trình nếu được ghi trong tour gốc","Nước uống hoặc bữa ăn theo mô tả của từng tour"]'::json, '["Chi phí cá nhân ngoài chương trình","Đồ uống, dịch vụ hoặc vé không được nêu trong phần bao gồm","Tiền tip cho hướng dẫn viên và tài xế nếu không được ghi rõ","Phụ thu phát sinh do thay đổi lịch trình, thời tiết hoặc yêu cầu riêng"]'::json, false, true),
    ('vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now', 'Tour Thánh địa Mỹ Sơn từ cảng Tiên Sa', 'Tour Thánh địa Mỹ Sơn từ cảng Tiên Sa là chương trình đã được DanangTrip chuẩn hóa từ dữ liệu công khai của đơn vị tổ chức. Tour có thời lượng 1 Day, giá tham khảo và lịch trình được đối chiếu từ nguồn gốc trước khi nhập vào hệ thống. Nội dung này đã được biên tập tiếng Việt ở mức sẵn sàng hiển thị, nhưng vẫn giữ tinh thần kiểm duyệt cuối cùng trước vận hành thương mại. Nguồn tham khảo: https://vmtravel.com/tours/my-son-sanctuary-tour-from-tien-sa-port/', 'Tour Thánh địa Mỹ Sơn từ cảng Tiên Sa, thời lượng 1 Day, đã có giá, ảnh Cloudinary và lịch khởi hành tương lai.', '["Đón khách và di chuyển đến khu di sản Thánh địa Mỹ Sơn.","Tham quan các cụm tháp Chăm và nghe giới thiệu về lịch sử vương quốc Champa.","Xem biểu diễn văn hóa hoặc trải nghiệm địa phương nếu lịch vận hành phù hợp.","Dùng bữa hoặc nghỉ ngơi theo chương trình tour.","Trả khách tại điểm đón ban đầu."]'::json, '["Xe đưa đón theo chương trình","Hướng dẫn viên theo ngôn ngữ công bố của đơn vị tổ chức","Vé tham quan theo lịch trình nếu được ghi trong tour gốc","Nước uống hoặc bữa ăn theo mô tả của từng tour"]'::json, '["Chi phí cá nhân ngoài chương trình","Đồ uống, dịch vụ hoặc vé không được nêu trong phần bao gồm","Tiền tip cho hướng dẫn viên và tài xế nếu không được ghi rõ","Phụ thu phát sinh do thay đổi lịch trình, thời tiết hoặc yêu cầu riêng"]'::json, false, true),
    ('vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece', 'Tour động Thiên Đường từ Huế', 'Tour động Thiên Đường từ Huế là chương trình đã được DanangTrip chuẩn hóa từ dữ liệu công khai của đơn vị tổ chức. Tour có thời lượng 1 Day, giá tham khảo và lịch trình được đối chiếu từ nguồn gốc trước khi nhập vào hệ thống. Nội dung này đã được biên tập tiếng Việt ở mức sẵn sàng hiển thị, nhưng vẫn giữ tinh thần kiểm duyệt cuối cùng trước vận hành thương mại. Nguồn tham khảo: https://vmtravel.com/tours/paradise-cave-tour-from-hue/', 'Tour động Thiên Đường từ Huế, thời lượng 1 Day, đã có giá, ảnh Cloudinary và lịch khởi hành tương lai.', '["Đón khách từ Huế và khởi hành đi khu vực Phong Nha - Kẻ Bàng.","Dừng tham quan các điểm trên đường theo lịch trình của đơn vị tổ chức.","Khám phá động Thiên Đường và hệ thống thạch nhũ nổi bật.","Dùng bữa, nghỉ ngơi và tiếp tục hành trình về Huế.","Trả khách tại khách sạn hoặc điểm hẹn đã xác nhận."]'::json, '["Xe đưa đón theo chương trình","Hướng dẫn viên theo ngôn ngữ công bố của đơn vị tổ chức","Vé tham quan theo lịch trình nếu được ghi trong tour gốc","Nước uống hoặc bữa ăn theo mô tả của từng tour"]'::json, '["Chi phí cá nhân ngoài chương trình","Đồ uống, dịch vụ hoặc vé không được nêu trong phần bao gồm","Tiền tip cho hướng dẫn viên và tài xế nếu không được ghi rõ","Phụ thu phát sinh do thay đổi lịch trình, thời tiết hoặc yêu cầu riêng"]'::json, false, false)
)
UPDATE tours target
SET
    name = editorial.name,
    description = editorial.description,
    short_desc = editorial.short_desc,
    itinerary = editorial.itinerary,
    inclusions = editorial.inclusions,
    exclusions = editorial.exclusions,
    status = 'active',
    booking_availability = 'open',
    is_featured = editorial.is_featured,
    is_hot = editorial.is_hot,
    updated_at = NOW()
FROM editorial
WHERE target.slug = editorial.slug;

UPDATE tours
SET
    meeting_point = CASE slug
        WHEN 'recrawl-018-venusvietnamtravel-afternoon-ba-na-hills-golden-bridge-dragon-bridge-by-night-tour-venustravel'
            THEN 'Đón khách tại khách sạn ở Hội An, Đà Nẵng hoặc Huế theo xác nhận của đơn vị tổ chức.'
        WHEN 'recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel'
            THEN 'Đón khách tại khách sạn ở Hội An, Đà Nẵng hoặc Huế theo xác nhận của đơn vị tổ chức.'
        WHEN 'vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour'
            THEN 'Đón khách tại Đà Nẵng hoặc Hội An theo lịch hẹn; vui lòng xác nhận điểm đón trước ngày khởi hành.'
        ELSE meeting_point
    END,
    updated_at = NOW()
WHERE slug IN (
    'recrawl-018-venusvietnamtravel-afternoon-ba-na-hills-golden-bridge-dragon-bridge-by-night-tour-venustravel',
    'recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel',
    'vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour'
);

COMMIT;
